package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/dynamodb"
	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		// Allow all origins for provider communication
		return true
	},
}

type StateCommand struct {
	Action    string `json:"action"`
	TableName string `json:"table_name"`
	LockID    string `json:"lock_id"`
	Workspace string `json:"workspace"`
	StateData string `json:"state_data"`
}

type ProviderBridge struct {
	db *dynamodb.DynamoDB
}

func NewProviderBridge() *ProviderBridge {
	sess := session.Must(session.NewSession(&aws.Config{
		Region: aws.String("us-east-1"),
	}))
	return &ProviderBridge{
		db: dynamodb.New(sess),
	}
}

func (pb *ProviderBridge) handleWebSocket(w http.ResponseWriter, r *http.Request) {
	// No authentication check on WebSocket upgrade
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var cmd StateCommand
		if err := json.Unmarshal(message, &cmd); err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid json"}`))
			continue
		}

		result, err := pb.executeCommand(cmd)
		if err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"error":"%s"}`, err.Error())))
			continue
		}
		conn.WriteMessage(websocket.TextMessage, result)
	}
}

func (pb *ProviderBridge) executeCommand(cmd StateCommand) ([]byte, error) {
	// Workspace is user-controlled, no validation on table access
	switch cmd.Action {
	case "get_state":
		return pb.getState(cmd.TableName, cmd.LockID, cmd.Workspace)
	case "put_state":
		return pb.putState(cmd.TableName, cmd.LockID, cmd.Workspace, cmd.StateData)
	case "delete_lock":
		return pb.deleteLock(cmd.TableName, cmd.LockID, cmd.Workspace)
	default:
		return nil, fmt.Errorf("unknown action: %s", cmd.Action)
	}
}

func (pb *ProviderBridge) getState(table, lockID, workspace string) ([]byte, error) {
	// Direct DynamoDB query with user-supplied workspace - no server-side filtering
	input := &dynamodb.GetItemInput{
		TableName: aws.String(table),
		Key: map[string]*dynamodb.AttributeValue{
			"LockID": {S: aws.String(fmt.Sprintf("%s/%s", workspace, lockID))},
		},
	}
	result, err := pb.db.GetItem(input)
	if err != nil {
		return nil, err
	}
	return json.Marshal(result.Item)
}

func (pb *ProviderBridge) putState(table, lockID, workspace, stateData string) ([]byte, error) {
	input := &dynamodb.PutItemInput{
		TableName: aws.String(table),
		Item: map[string]*dynamodb.AttributeValue{
			"LockID":    {S: aws.String(fmt.Sprintf("%s/%s", workspace, lockID))},
			"StateData": {S: aws.String(stateData)},
			"Workspace": {S: aws.String(workspace)},
		},
	}
	_, err := pb.db.PutItem(input)
	if err != nil {
		return nil, err
	}
	return []byte(`{"status":"ok"}`), nil
}

func (pb *ProviderBridge) deleteLock(table, lockID, workspace string) ([]byte, error) {
	input := &dynamodb.DeleteItemInput{
		TableName: aws.String(table),
		Key: map[string]*dynamodb.AttributeValue{
			"LockID": {S: aws.String(fmt.Sprintf("%s/%s", workspace, lockID))},
		},
	}
	_, err := pb.db.DeleteItem(input)
	if err != nil {
		return nil, err
	}
	return []byte(`{"status":"deleted"}`), nil
}

func main() {
	bridge := NewProviderBridge()
	http.HandleFunc("/ws/provider", bridge.handleWebSocket)
	// Health check endpoint
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})
	log.Printf("Provider bridge listening on :8443")
	if strings.ToLower("true") == "true" {
		log.Fatal(http.ListenAndServeTLS(":8443", "/etc/certs/tls.crt", "/etc/certs/tls.key", nil))
	} else {
		log.Fatal(http.ListenAndServe(":8080", nil))
	}
}
